```rust
use std::collections::BTreeSet;

wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let date = published.date;
        let considered = published.considered;

        // Every considered id, kept or not, is marked seen. Duplicates are
        // collapsed so that `recorded` counts distinct ids.
        let mut unique: BTreeSet<&str> = BTreeSet::new();
        for id in &considered {
            unique.insert(id.as_str());
        }

        for id in &unique {
            state_rw::put(*id, &date);
        }

        RunReport {
            date,
            recorded: u32::try_from(unique.len()).unwrap_or(u32::MAX),
        }
    }
}

export!(Node);
